<?php
 namespace Slim; class Log { const EMERGENCY = 1; const ALERT = 2; const CRITICAL = 3; const FATAL = 3; const ERROR = 4; const WARN = 5; const NOTICE = 6; const INFO = 7; const DEBUG = 8; protected static $levels = array( self::EMERGENCY => 'EMERGENCY', self::ALERT => 'ALERT', self::CRITICAL => 'CRITICAL', self::ERROR => 'ERROR', self::WARN => 'WARNING', self::NOTICE => 'NOTICE', self::INFO => 'INFO', self::DEBUG => 'DEBUG' ); protected $writer; protected $enabled; protected $level; public function __construct($writer) { $this->writer = $writer; $this->enabled = true; $this->level = self::DEBUG; } public function getEnabled() { return $this->enabled; } public function setEnabled($enabled) { if ($enabled) { $this->enabled = true; } else { $this->enabled = false; } } public function setLevel($level) { if (!isset(self::$levels[$level])) { throw new \InvalidArgumentException('Invalid log level'); } $this->level = $level; } public function getLevel() { return $this->level; } public function setWriter($writer) { $this->writer = $writer; } public function getWriter() { return $this->writer; } public function isEnabled() { return $this->enabled; } public function debug($object, $context = array()) { return $this->log(self::DEBUG, $object, $context); } public function info($object, $context = array()) { return $this->log(self::INFO, $object, $context); } public function notice($object, $context = array()) { return $this->log(self::NOTICE, $object, $context); } public function warning($object, $context = array()) { return $this->log(self::WARN, $object, $context); } public function warn($object, $context = array()) { return $this->log(self::WARN, $object, $context); } public function error($object, $context = array()) { return $this->log(self::ERROR, $object, $context); } public function critical($object, $context = array()) { return $this->log(self::CRITICAL, $object, $context); } public function fatal($object, $context = array()) { return $this->log(self::CRITICAL, $object, $context); } public function alert($object, $context = array()) { return $this->log(self::ALERT, $object, $context); } public function emergency($object, $context = array()) { return $this->log(self::EMERGENCY, $object, $context); } public function log($level, $object, $context = array()) { if (!isset(self::$levels[$level])) { throw new \InvalidArgumentException('Invalid log level supplied to function'); } else if ($this->enabled && $this->writer && $level <= $this->level) { if (is_array($object) || (is_object($object) && !method_exists($object, "__toString"))) { $message = print_r($object, true); } else { $message = (string) $object; } if (count($context) > 0) { if (isset($context['exception']) && $context['exception'] instanceof \Exception) { $message .= ' - ' . $context['exception']; unset($context['exception']); } $message = $this->interpolate($message, $context); } return $this->writer->write($message, $level); } else { return false; } } protected function write($object, $level) { return $this->log($level, $object); } protected function interpolate($message, $context = array()) { $replace = array(); foreach ($context as $key => $value) { $replace['{' . $key . '}'] = $value; } return strtr($message, $replace); } } 